mapper.select:
SELECT A.group_seq ,A.group_code ,A.group_name ,B.code_seq ,B.code ,B.code_name ,B.create_user ,B.create_at FROM utb_group_code A LEFT OUTER JOIN utb_common_code B ON A.group_seq = B.group_seq
AND B.code_seq = #{codeSeq}
AND A.group_code IN
#{code}
AND A.group_name LIKE CONCAT('%', #{groupName}, '%')
AND B.code_name LIKE CONCAT('%', #{codeName}, '%')
AND B.code IN
#{cd}
AND A.del_yn = 'N' AND B.del_yn = 'N'
ORDER BY B.order ASC

mapper.insert:
INSERT INTO utb_common_code(
   group_seq
   , code
   , code_name
   , del_yn
   , create_user
   , create_at

)
VALUES(
    #{groupSeq}
      , #{code}
      , #{codeName}
      , 'N'
      , #{createUser}
      , NOW()
)

UPDATE utb_common_code SET
   group_name = #{groupName}
   , code_name = #{codeName}
   , del_yn = #{delYn}
   , update_user = #{updateUser}
   , update_at = NOW()
WHERE code_seq = #{codeSeq}

INSERT INTO utb_group_code(
     group_code
   , group_name
