   , create_user
   , create_at
)
VALUES(
        #{groupCode}
      , #{groupName}
      , 'N'
      , #{createUser}
      , NOW()
  )

mapper.update:
UPDATE utb_group_code SET
    group_name = #{groupName}
     , del_yn = #{delYn}
     , update_user = #{updateUser}
     , update_at = NOW()
WHERE group_seq = #{groupSeq}

mapper.select:
SELECT d.code_seq, d.grp_cd, d.dtl_cd, d.cd_nm, d.kipo_cd, d.ref_val_1, d.ref_val_2, d.disp_ord, d.use_yn, d.del_yn, d.note FROM utb_code_dtl d INNER JOIN utb_code_mst m ON m.grp_cd = d.grp_cd AND m.del_yn = 'N' AND m.use_yn = 'Y' WHERE d.del_yn = 'N' AND d.use_yn = 'Y' AND d.grp_cd IN
#{item}
ORDER BY d.grp_cd ASC, d.disp_ord ASC

SELECT doc_seq::text AS "docSeq", doc_div AS "docDiv", entry_type AS "entryType", pat_type AS "patType", doc_nm AS "docNm", auto_yn AS "autoYn", base_date_type AS "baseDateType", deadline_unit AS "deadlineUnit", deadline_val::text AS "deadlineVal", ref_val AS "refVal", sort_ord::text AS "sortOrd", create_user AS "createUser", create_at AS "createAt", update_user AS "updateUser", update_at AS "updateAt", del_yn AS "delYn", note AS "note" FROM utb_document_mst WHERE del_yn = 'N'
AND entry_type = #{entryType}
AND pat_type = #{patType}
AND doc_div = #{docDiv}
ORDER BY sort_ord ASC, doc_nm ASC
